import { ChevronRight } from 'lucide-react';
import { useId, type HTMLAttributes, type MouseEventHandler, type ReactNode, type Ref } from 'react';
import { cn } from '../../utils/cn';
import { clickableCardVariants } from './choice-card.variants';

const s = clickableCardVariants();

export interface ClickableCardProps extends Omit<HTMLAttributes<HTMLDivElement>, 'className' | 'title' | 'onClick'> {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** The card's name — the text of its single link or button. */
  title: ReactNode;
  description?: ReactNode;
  /** Secondary line under the description (badges, counts, a timestamp). */
  meta?: ReactNode;
  /** Leading icon tile (pass a lucide icon with `aria-hidden`). */
  icon?: ReactNode;
  /** Renders the card as a link. */
  href?: string;
  /** Renders the card as a button (or runs alongside `href`). */
  onClick?: MouseEventHandler<HTMLElement>;
  /** Heading element around the title, to fit the page outline; defaults to none. */
  titleAs?: 'h2' | 'h3' | 'h4' | 'span';
  /** Trailing chevron hint. */
  chevron?: boolean;
  disabled?: boolean;
}

/**
 * A card whose whole surface is one link or button. The title holds the only focus target and
 * stretches over the card, so the accessible name stays short and the description is linked
 * with aria-describedby. Extra interactive content inside needs `relative z-10`.
 */
export function ClickableCard({
  title,
  description,
  meta,
  icon,
  href,
  onClick,
  titleAs: Title = 'span',
  chevron = true,
  disabled = false,
  className,
  children,
  ...props
}: ClickableCardProps) {
  const descId = useId();
  const describedBy = description != null ? descId : undefined;
  const action =
    href != null && !disabled ? (
      <a href={href} onClick={onClick} aria-describedby={describedBy} className={cn(s.action(), s.title())}>
        {title}
      </a>
    ) : (
      <button type="button" onClick={onClick} disabled={disabled} aria-describedby={describedBy} className={cn(s.action(), s.title())}>
        {title}
      </button>
    );
  return (
    <div data-disabled={disabled || undefined} className={cn('group/card', s.root(), className)} {...props}>
      {icon != null && <span className={s.icon()}>{icon}</span>}
      <div className={s.body()}>
        <Title className="block">{action}</Title>
        {description != null && (
          <span id={descId} className={s.description()}>
            {description}
          </span>
        )}
        {meta != null && <div className={s.meta()}>{meta}</div>}
        {children}
      </div>
      {chevron && <ChevronRight aria-hidden className={s.chevron()} />}
    </div>
  );
}

import { Checkbox as BaseCheckbox } from '@base-ui/react/checkbox';
import { CheckboxGroup as BaseCheckboxGroup } from '@base-ui/react/checkbox-group';
import { Radio as BaseRadio } from '@base-ui/react/radio';
import { RadioGroup as BaseRadioGroup } from '@base-ui/react/radio-group';
import { Check } from 'lucide-react';
import { createContext, useContext, useId, type AriaAttributes, type ReactNode, type Ref } from 'react';
import { cn } from '../../utils/cn';
import { selectableCardVariants, type SelectableCardVariantProps } from './choice-card.variants';

type ChoiceType = 'radio' | 'checkbox';
const TypeContext = createContext<ChoiceType>('radio');

interface GroupCommon extends Pick<AriaAttributes, 'aria-label' | 'aria-labelledby' | 'aria-describedby'> {
  className?: string;
  ref?: Ref<HTMLDivElement>;
  /** Grid columns from the `sm` breakpoint. */
  columns?: SelectableCardVariantProps['columns'];
  disabled?: boolean;
  id?: string;
  children?: ReactNode;
}

export interface SelectableCardRadioGroupProps extends GroupCommon {
  /** Single choice (role radiogroup; arrows move and select). */
  type?: 'radio';
  /** Form field name. */
  name?: string;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
}

export interface SelectableCardCheckboxGroupProps extends GroupCommon {
  /** Multiple choice (role group; Space toggles each card). */
  type: 'checkbox';
  value?: string[];
  defaultValue?: string[];
  onValueChange?: (value: string[]) => void;
}

export type SelectableCardGroupProps = SelectableCardRadioGroupProps | SelectableCardCheckboxGroupProps;

/**
 * Grid of SelectableCards with radio (default) or checkbox semantics, on Base UI RadioGroup /
 * CheckboxGroup. Name it with `aria-labelledby` (or `aria-label`).
 */
export function SelectableCardGroup(props: SelectableCardGroupProps) {
  const { columns, className, ...common } = props;
  const groupClass = cn(selectableCardVariants({ columns }).group(), className);
  const shared = {
    className: groupClass,
    ref: common.ref,
    id: common.id,
    disabled: common.disabled,
    'aria-label': common['aria-label'],
    'aria-labelledby': common['aria-labelledby'],
    'aria-describedby': common['aria-describedby'],
    children: common.children,
  };
  if (props.type === 'checkbox') {
    const { value, defaultValue, onValueChange } = props;
    return (
      <TypeContext.Provider value="checkbox">
        <BaseCheckboxGroup {...shared} value={value} defaultValue={defaultValue} onValueChange={(v) => onValueChange?.(v)} />
      </TypeContext.Provider>
    );
  }
  const { value, defaultValue, onValueChange, name } = props;
  return (
    <TypeContext.Provider value="radio">
      <BaseRadioGroup<string>
        {...shared}
        name={name}
        value={value}
        defaultValue={defaultValue}
        onValueChange={(v) => onValueChange?.(v)}
      />
    </TypeContext.Provider>
  );
}

export interface SelectableCardProps {
  /** Identifies the card inside its group. */
  value: string;
  /** The card's accessible name. */
  title: ReactNode;
  description?: ReactNode;
  /** Secondary content (price, badge, specs); announced as part of the description. */
  meta?: ReactNode;
  /** Leading icon tile. */
  icon?: ReactNode;
  disabled?: boolean;
  className?: string;
}

/** One option card: indicator, title, description and meta; the whole card toggles it. */
export function SelectableCard({ value, title, description, meta, icon, disabled, className }: SelectableCardProps) {
  const type = useContext(TypeContext);
  const s = selectableCardVariants({ type });
  const titleId = useId();
  const descId = useId();
  const metaId = useId();
  const describedBy = [description != null && descId, meta != null && metaId].filter(Boolean).join(' ') || undefined;
  const a11y = { 'aria-labelledby': titleId, 'aria-describedby': describedBy };
  const control =
    type === 'checkbox' ? (
      <BaseCheckbox.Root value={value} disabled={disabled} {...a11y} className={s.control()}>
        <BaseCheckbox.Indicator className={s.indicator()}>
          <Check size={13} strokeWidth={2.6} aria-hidden />
        </BaseCheckbox.Indicator>
      </BaseCheckbox.Root>
    ) : (
      <BaseRadio.Root<string> value={value} disabled={disabled} {...a11y} className={s.control()}>
        <BaseRadio.Indicator className={s.indicator()} />
      </BaseRadio.Root>
    );
  return (
    <label className={cn(s.root(), className)}>
      {icon != null && <span className={s.icon()}>{icon}</span>}
      <span className={s.body()}>
        <span id={titleId} className={s.title()}>
          {title}
        </span>
        {description != null && (
          <span id={descId} className={s.description()}>
            {description}
          </span>
        )}
        {meta != null && (
          <span id={metaId} className={s.meta()}>
            {meta}
          </span>
        )}
      </span>
      {control}
    </label>
  );
}

import { tv, type VariantProps } from '../../utils/tv';

const SURFACE = [
  'relative flex items-start gap-3.5 rounded-md border border-border bg-background px-4 py-3.5 text-start transition-colors motion-reduce:transition-none',
  'has-[:focus-visible]:outline-2 has-[:focus-visible]:outline-offset-2 has-[:focus-visible]:outline-focus-ring',
];

/** Shared text slots of both cards. */
const TEXT = {
  icon: 'grid size-9 shrink-0 place-items-center rounded-md bg-secondary text-muted-foreground [&_svg]:size-4.5',
  body: 'min-w-0 flex-1',
  title: 'block text-[13px] leading-5 font-semibold text-foreground',
  description: 'mt-0.5 block text-[12px] leading-5 text-muted-foreground text-pretty',
  meta: 'mt-2 flex flex-wrap items-center gap-2 text-[12px] text-muted-foreground',
};

export const clickableCardVariants = tv({
  slots: {
    root: [...SURFACE, 'hover:border-muted-foreground/40 hover:bg-secondary/30', 'data-disabled:opacity-60 data-disabled:hover:border-border data-disabled:hover:bg-background'],
    ...TEXT,
    /** The link/button; its ::after covers the card so the whole surface is clickable. */
    action: [
      'cursor-pointer text-start outline-none after:absolute after:inset-0 after:rounded-[inherit] after:content-[""]',
      'disabled:cursor-not-allowed aria-disabled:cursor-not-allowed',
    ],
    chevron: 'mt-0.5 size-4 shrink-0 text-muted-foreground transition-transform motion-reduce:transition-none group-hover/card:translate-x-0.5 rtl:-scale-x-100 rtl:group-hover/card:-translate-x-0.5',
  },
});

export const selectableCardVariants = tv({
  slots: {
    group: 'grid gap-3',
    root: [
      ...SURFACE,
      'cursor-pointer hover:border-muted-foreground/40 has-[[data-checked]]:border-primary/60 has-[[data-checked]]:ring-2 has-[[data-checked]]:ring-primary/20',
      'has-[[data-disabled]]:cursor-not-allowed has-[[data-disabled]]:opacity-60 has-[[data-disabled]]:hover:border-border',
    ],
    ...TEXT,
    control: [
      'mt-0.5 inline-flex size-[18px] shrink-0 items-center justify-center border border-border bg-background outline-none',
      'transition-colors motion-reduce:transition-none data-checked:border-primary data-checked:bg-primary',
    ],
    indicator: 'flex items-center justify-center text-primary-foreground data-unchecked:hidden',
  },
  variants: {
    type: {
      radio: { control: 'rounded-full', indicator: 'size-1.5 rounded-full bg-primary-foreground' },
      checkbox: { control: 'rounded-[5px]' },
    },
    columns: {
      1: { group: 'grid-cols-1' },
      2: { group: 'sm:grid-cols-2' },
      3: { group: 'sm:grid-cols-3' },
    },
  },
  defaultVariants: { type: 'radio', columns: 1 },
});

export type SelectableCardVariantProps = VariantProps<typeof selectableCardVariants>;

export { ClickableCard, type ClickableCardProps } from './ClickableCard';
export {
  SelectableCardGroup,
  SelectableCard,
  type SelectableCardGroupProps,
  type SelectableCardRadioGroupProps,
  type SelectableCardCheckboxGroupProps,
  type SelectableCardProps,
} from './SelectableCard';
export { clickableCardVariants, selectableCardVariants, type SelectableCardVariantProps } from './choice-card.variants';
export { doc as choiceCardDoc } from './ChoiceCard.doc';

import type { ComponentDoc } from '../../doc';

export const doc: ComponentDoc = {
  name: 'ChoiceCard',
  group: 'Forms',
  status: 'beta',
  description: 'Cards as controls. ClickableCard: the whole card is one link or button (a stretched title, so there is a single focus target with a short name) with icon, description, meta and a chevron. SelectableCard inside SelectableCardGroup: option cards with radio (single) or checkbox (multiple) semantics on Base UI RadioGroup / CheckboxGroup, with a check indicator, title, description, meta and disabled state.',
  primitive: '@base-ui/react/radio-group · @base-ui/react/checkbox-group',
  pattern: 'link / button · radiogroup · group of checkboxes',
  keyboard: [
    ['Tab', 'ClickableCard: focuses its link or button. Group: enters the radio group once, on the selected card; visits each checkbox card'],
    ['Enter', 'Activates a ClickableCard'],
    ['Arrow keys', 'Radio group: move to the next / previous card and select it'],
    ['Space', 'Checkbox group: toggles the focused card (radio: selects it)'],
  ],
  tokens: ['background', 'border', 'secondary', 'foreground', 'muted-foreground', 'primary', 'primary-foreground', 'focus-ring'],
};

/**
 * Component documentation contract. Every component folder exports a `*.doc.ts`
 * with this shape; the registry build and the docs site read it.
 */
export interface ComponentDoc {
  /** Public component name, e.g. "Button". */
  name: string;
  /** Inventory group, e.g. "Actions", "Forms", "Overlays". */
  group: 'Actions' | 'Forms' | 'Overlays' | 'Navigation' | 'Display' | 'Feedback' | 'Layout' | 'Theme';
  /** Lifecycle badge. */
  status: 'stable' | 'beta' | 'experimental';
  description: string;
  /** Headless primitive it is built on, if any (e.g. "@base-ui/react/dialog"). */
  primitive?: string;
  /** WAI-ARIA pattern the a11y contract test checks. */
  pattern?: string;
  /** Keyboard contract: key → behaviour. Each row is covered by a test. */
  keyboard?: Array<[key: string, behaviour: string]>;
  /** Tokens the component reads (for the theming docs). */
  tokens?: string[];
}
